<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
const portrait=ref(false),mobile=ref(false),message=ref('')
function update(){mobile.value=innerWidth<=1000&&innerHeight<=1000;portrait.value=mobile.value&&innerHeight>innerWidth;document.documentElement.style.setProperty('--ninja-viewport-height',(visualViewport?.height??innerHeight)+'px')}
let messageTimer:ReturnType<typeof setTimeout>|undefined
function dismiss(){clearTimeout(messageTimer);message.value=''}
function notify(text:string){dismiss();message.value=text;messageTimer=setTimeout(dismiss,4000)}
async function immerse(){
 dismiss()
 try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen(); const orientation=screen.orientation as ScreenOrientation & {lock?:(mode:string)=>Promise<void>};if(orientation.lock)await orientation.lock('landscape');else notify('当前浏览器不支持方向锁定，请手动旋转。')}catch{notify('无法自动全屏或锁定方向，可手动旋转继续游戏。')}finally{update()}
}
onMounted(()=>{update();addEventListener('resize',update);document.addEventListener('fullscreenchange',update);visualViewport?.addEventListener('resize',update)})
onUnmounted(()=>{dismiss();document.documentElement.style.removeProperty('--ninja-viewport-height');removeEventListener('resize',update);document.removeEventListener('fullscreenchange',update);visualViewport?.removeEventListener('resize',update)})
</script>
<template><section v-if="mobile" class="nn-viewport-controls" :data-orientation="portrait?'portrait':'landscape'" aria-label="横屏显示"><span v-if="portrait">建议旋转手机横屏；竖屏仍可继续操作。</span><button type="button" @click="immerse">全屏横屏</button><Teleport to="body"><div v-if="message && mobile" class="nn-fullscreen-notice" role="status">{{ message }}<button type="button" aria-label="关闭全屏提示" @click="dismiss">关闭</button></div></Teleport></section></template>
<style scoped>.nn-viewport-controls{position:relative;display:flex;align-items:center;gap:.4rem;padding:max(.15rem,env(safe-area-inset-top)) max(.3rem,env(safe-area-inset-right)) .15rem max(.3rem,env(safe-area-inset-left));font-size:.75rem}.nn-viewport-controls button{min-height:32px;padding:.2rem .5rem}.nn-viewport-controls span[role=status]:empty{display:none}@media(orientation:landscape) and (max-width:1000px) and (max-height:500px){.nn-viewport-controls{padding:0;position:relative}.nn-viewport-controls span[role=status]:not(:empty){position:absolute;right:0;top:100%;width:min(280px,80vw);padding:6px;background:#171c2b;z-index:20}}@media(orientation:portrait){.nn-viewport-controls>span:first-child{position:absolute;right:0;top:100%;width:180px;padding:4px;background:#171c2b;z-index:10}}.nn-fullscreen-notice{position:fixed;left:50%;top:max(4px,env(safe-area-inset-top));transform:translateX(-50%);z-index:30;display:flex;gap:8px;align-items:center;max-width:calc(100vw - 20px);padding:8px 12px;background:#171c2b;color:#f1e3cb;border:1px solid #aa8a57;border-radius:8px;font-size:12px;box-sizing:border-box}.nn-fullscreen-notice button{min-height:32px;white-space:nowrap}:global(body:has(.nn-fullscreen-notice) main.game-page:has(>.nn-p20)){padding-top:58px;box-sizing:border-box}@media(orientation:landscape) and (max-width:1000px) and (max-height:500px){.nn-fullscreen-notice{top:1px;padding:0 6px;font-size:11px;white-space:nowrap;max-width:calc(100vw - 12px)}:global(body:has(.nn-fullscreen-notice) main.game-page:has(>.nn-p20)){padding-top:2px}}</style>
